def taller_within(a: list[int], k: int) -> list[int]:
    if k == 0:
        return [0] * len(a)

    values = sorted(set(a))
    ranks = {value: i + 1 for i, value in enumerate(values)}
    tree = [0] * (len(values) + 1)
    size = len(values)
    result = []

    for i, value in enumerate(a):
        if i > k:
            rank = ranks[a[i - k - 1]]
            while rank <= size:
                tree[rank] -= 1
                rank += rank & -rank

        rank = ranks[value]
        count_not_taller = 0
        pos = rank
        while pos:
            count_not_taller += tree[pos]
            pos -= pos & -pos

        result.append(min(i, k) - count_not_taller)

        while rank <= size:
            tree[rank] += 1
            rank += rank & -rank

    return result
